public struct ImagePipeline {                 // the public API is the facade
    private let downloader: ImageDownloading   // internal protocols, injected
    private let cache: ImageCaching

    public func load(from url: URL) async throws -> Image {
        if let hit = cache.image(for: url) { return hit }
        let image = try await downloader.fetch(url)
        cache.store(image, for: url)
        return image
    }
}
